// Run with: npm run make:seed
// Turns the clip files in src/data/clips into supabase/seed.sql (clips + sentences).
import { writeFileSync, mkdirSync } from 'node:fs';
import { clips } from '../src/data/clips/index.js';

const q = (v) => `'${String(v).replace(/'/g, "''")}'`;
const json = (v) => `${q(JSON.stringify(v ?? {}))}::jsonb`;

const lines = [
  '-- Generated by scripts/make-seed.mjs from src/data/clips. Do not edit by hand.',
  '-- Paste into the Supabase SQL Editor AFTER schema.sql. Safe to run again.',
  '',
];

for (const c of clips) {
  lines.push(
    `insert into public.clips (id, source, video_id, title, accent, difficulty, context_ko) values (${[
      q(c.id), q(c.source), q(c.videoId), q(c.title), q(c.accent), c.difficulty, q(c.contextKo),
    ].join(', ')})`,
    `on conflict (id) do update set source = excluded.source, video_id = excluded.video_id, title = excluded.title,`,
    `  accent = excluded.accent, difficulty = excluded.difficulty, context_ko = excluded.context_ko;`,
    ''
  );
  c.sentences.forEach((s, i) => {
    lines.push(
      `insert into public.sentences (clip_id, sentence_id, position, start_time, end_time, text, ko, key_words, glosses, tts_audio) values (${[
        q(c.id), q(s.id), i + 1, s.start, s.end, q(s.text), q(s.ko), json(s.keyWords ?? []), json(s.glosses), json(s.ttsAudio),
      ].join(', ')})`,
      `on conflict (clip_id, sentence_id) do update set position = excluded.position, start_time = excluded.start_time,`,
      `  end_time = excluded.end_time, text = excluded.text, ko = excluded.ko, key_words = excluded.key_words,`,
      `  glosses = excluded.glosses, tts_audio = excluded.tts_audio;`
    );
  });
  lines.push('');
}

mkdirSync('supabase', { recursive: true });
writeFileSync('supabase/seed.sql', lines.join('\n'));
console.log(`Wrote supabase/seed.sql (${clips.length} clips, ${clips.reduce((n, c) => n + c.sentences.length, 0)} sentences).`);
